def minAbsoluteDifference(nums):
    INF = len(nums) + 1
    best = INF
    last1 = -1   # most recent index holding a 1
    last2 = -1   # most recent index holding a 2
    for i in range(len(nums)):
        if nums[i] == 1:
            last1 = i
            # Pair this 1 with the closest earlier 2
            if last2 != -1:
                best = min(best, i - last2)
        elif nums[i] == 2:
            last2 = i
            # Pair this 2 with the closest earlier 1
            if last1 != -1:
                best = min(best, i - last1)
    if best == INF:
        return -1
    return best
